sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !newValue) return;

    g_form.hideFieldMsg('base');

    var ga = new GlideAjax('CheckBaseCapacity');
    ga.addParam('sysparm_name', 'checkIfBaseIsFull');
    ga.addParam('sysparm_base_id', newValue); 
    ga.getXMLAnswer(function(response) {
        if (response === 'true') {

            g_form.setValue('base', '');
            g_form.showFieldMsg('base', 'This base has reached its maximum capacity. Please select another one.', 'error');
        }
    });
}
